// ===========================================================================
// SETTINGS: built from the job row written by the web page.
//
// DEFAULTS apply when the job doesn't set a value. LIMITS are enforced here
// as well as in the web page, so a hand-edited row can't push values out of
// range. The restricted-client list is NOT here; it stays in
// "Check restricted list" on purpose.
// ===========================================================================

const DEFAULTS = {
  ngram_max: 4,
  dedupe_threshold: 0.85,
  top_n: 500,
  min_segments: 2,
  min_chars: 15,
  include_examples: 3,
  dedupe_segments: true,
  independence_ratio: 1.25,
  run_ai_review: false,
  ai_review_approved: false,
};

const LIMITS = {
  ngram_max: [1, 6, true],
  dedupe_threshold: [0.5, 1, false],
  top_n: [10, 5000, true],
  min_segments: [1, 50, true],
  min_chars: [0, 200, true],
  include_examples: [0, 10, true],
  independence_ratio: [1, 5, false],
};

const job = $('Pick next job').first().json;

let fromJob;
try {
  fromJob = JSON.parse(job.settings_json || '{}');
} catch (e) {
  throw new Error(`Job ${job.job_id}: settings_json is not valid JSON.`);
}

const settings = { ...DEFAULTS };
for (const [key, [min, max, integer]] of Object.entries(LIMITS)) {
  const n = Number(fromJob[key]);
  if (fromJob[key] === undefined || fromJob[key] === '' || Number.isNaN(n)) continue;
  const clamped = Math.min(max, Math.max(min, n));
  settings[key] = integer ? Math.round(clamped) : clamped;
}
settings.dedupe_segments = fromJob.dedupe_segments !== false;
settings.run_ai_review = fromJob.run_ai_review === true;
settings.ai_review_approved = settings.run_ai_review && fromJob.ai_review_approved === true;

settings.client = String(fromJob.client || job.client || '').trim();
settings.source_lang = String(fromJob.source_lang || job.source_lang || 'en').toLowerCase();
// What the language is called inside TMX files; may differ from the stopword
// key (Czech is 'cz' in YAKE but 'cs' in TMX). Comma-separated prefixes.
settings.tmx_lang = String(fromJob.tmx_lang || settings.source_lang).toLowerCase();
settings.input_mode = 'drive';

settings.job_id = job.job_id;
settings.submitted_by = job.submitted_by || '';
settings.input_folder_id = job.input_folder_id;
settings.output_folder_id = job.output_folder_id;

if (!settings.client) throw new Error(`Job ${job.job_id}: no client name.`);
if (!settings.input_folder_id || !settings.output_folder_id) {
  throw new Error(`Job ${job.job_id}: input or output folder ID missing from the Jobs sheet.`);
}

return [{ json: settings }];

// ===========================================================================
// STOPWORD LISTS
//
// YAKE's own stopword lists, extracted from the Python package, so this
// workflow and any future Python component treat word boundaries the same
// way. 34 languages.
//
// Stopwords do one job here: they mark where a candidate phrase ends. Too few
// and verb phrases slip through; too many and real terms get cut in half.
//
// The long list below is one line. Scroll past it to the editable settings.
// ===========================================================================

