// --- EDITABLE: extra boundary words ---------------------------------------
// YAKE's general-purpose lists don't include these, but they rarely belong in
// a technical glossary. Add your own as you see what comes out.
const EXTRA_STOPWORDS = {
  en: ['ten', 'previous', 'make', 'makes', 'made', 'shown', 'based', 'ensure', 'ensuring',
       'provide', 'provided', 'require', 'required', 'requires', 'refer', 'referring',
       'including', 'include', 'includes', 'fitted', 'complete', 'confirm'],
};

// --- EDITABLE: connector words --------------------------------------------
// Stopwords that may appear INSIDE a term but never at its start or end.
// Essential for Romance languages, where multi-word terms are built with
// prepositions. Without 'di', "valvola di sicurezza" splits into "valvola" +
// "sicurezza", and "messa in servizio" is lost entirely.
//
// Keep these SHORT. Every word added lets candidates grow longer and noisier.
const CONNECTORS = {
  en: ['of', 'for'],
  it: ['di', 'del', 'della', 'dello', 'dei', 'delle', 'in', 'nel', 'nella',
       'da', 'a', 'al', 'alla', 'per', 'con', 'su', 'sul'],
  es: ['de', 'del', 'en', 'para', 'por', 'con', 'a', 'al'],
  fr: ['de', 'du', 'des', 'en', 'au', 'aux', 'pour', 'par', 'sur', 'avec'],
  pt: ['de', 'do', 'da', 'dos', 'das', 'em', 'para', 'por', 'com', 'ao'],
  de: ['von', 'im', 'zur', 'zum'],
  nl: ['van', 'voor', 'in', 'op', 'met'],
  ro: ['de', 'la', 'cu', 'pentru', 'din'],
  pl: ['do', 'na', 'w', 'z', 'dla'],
};

// ---------------------------------------------------------------------------
const settings = $('Settings').first().json;
const lang = String(settings.source_lang || 'en').toLowerCase().split(/[-_]/)[0];

const base = STOPWORD_LISTS[lang];
if (!base) {
  throw new Error(
    `No stopword list for language "${lang}". Available: ${Object.keys(STOPWORD_LISTS).sort().join(', ')}`
  );
}

const extra = EXTRA_STOPWORDS[lang] || [];
const connectors = (CONNECTORS[lang] || []).map((w) => w.toLowerCase());

return [
  {
    json: {
      language: lang,
      stopwords: base,
      extra_stopwords: extra,
      connectors,
      counts: {
        yake: base.length,
        extra: extra.length,
        connectors: connectors.length,
        total: new Set([...base, ...extra]).size,
      },
      languages_available: Object.keys(STOPWORD_LISTS).sort(),
    },
  },
];

// ===========================================================================
// Turns Google Drive downloads into the shape stage 1 expects.
//
// Expects each incoming item to carry the downloaded file as binary property
// 'data'. If your Drive node names it differently, change BINARY_PROPERTY.
// ===========================================================================

const BINARY_PROPERTY = 'data';

const EXT_TO_TYPE = { tmx: 'tmx', xml: 'tmx', txt: 'text', md: 'text' };

// TMX exports (MemoQ, Trados) are often UTF-16, not UTF-8. Reading UTF-16 as
// UTF-8 interleaves NUL characters through the text and every regex in
// stage 1 then finds nothing. Detect by byte-order mark first, then by the
// pattern of zero bytes for files saved without one.
function detectEncoding(buf) {
  if (buf.length >= 3 && buf[0] === 0xef && buf[1] === 0xbb && buf[2] === 0xbf) return 'utf8-bom';
  if (buf.length >= 2 && buf[0] === 0xff && buf[1] === 0xfe) return 'utf16le';
  if (buf.length >= 2 && buf[0] === 0xfe && buf[1] === 0xff) return 'utf16be';
  const sample = Math.min(buf.length, 4096);
  let evenZeros = 0;
  let oddZeros = 0;
  for (let i = 0; i < sample; i += 1) {
    if (buf[i] === 0) { if (i % 2 === 0) evenZeros += 1; else oddZeros += 1; }
  }
  const half = sample / 2 || 1;
  if (oddZeros / half > 0.3 && evenZeros / half < 0.05) return 'utf16le';
  if (evenZeros / half > 0.3 && oddZeros / half < 0.05) return 'utf16be';
  return 'utf8';
}

function decodeText(buf) {
  const enc = detectEncoding(buf);
  if (enc === 'utf8-bom') return buf.subarray(3).toString('utf8');
  if (enc === 'utf16le') return buf.toString('utf16le').replace(/^\uFEFF/, '');
  if (enc === 'utf16be') {
    const even = buf.length - (buf.length % 2);
    const swapped = Buffer.from(buf.subarray(0, even));
    swapped.swap16();
    return swapped.toString('utf16le').replace(/^\uFEFF/, '');
  }
  return buf.toString('utf8');
}

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i += 1) {
  const item = items[i];
  const binary = (item.binary || {})[BINARY_PROPERTY];

  const name = (binary && binary.fileName) || item.json.name || `file_${i + 1}`;
  const ext = (name.split('.').pop() || '').toLowerCase();
  const sourceType = EXT_TO_TYPE[ext];

  if (!sourceType) {
    // PDF and DOCX need an Extract from File node first; skipped, not failed.
    out.push({ json: { file_name: name, source_type: 'unsupported', content: '', skipped: `unsupported_extension:${ext}` } });
    continue;
  }

  if (!binary) {
    throw new Error(
      `Item ${i + 1} ("${name}") has no binary property "${BINARY_PROPERTY}". ` +
      `Check the Drive node is set to download the file, not just list it.`
    );
  }

  const buffer = await this.helpers.getBinaryDataBuffer(i, BINARY_PROPERTY);
  out.push({ json: { file_name: name, source_type: sourceType, content: decodeText(buffer), encoding: detectEncoding(buffer) } });
}

return out;

// ===========================================================================
// The handoff point. Everything upstream of here just has to produce items
// shaped like:
//
//   { file_name: 'acme.tmx', source_type: 'tmx' | 'text', content: '<string>' }
//
// If you rebuild the Drive nodes by hand, connect them into this node and
// nothing downstream needs changing.
// ===========================================================================

const items = $input.all();
if (!items.length) {
  throw new Error('No documents arrived. Check Settings.input_mode and the branch it selects.');
}

const usable = items.filter((i) => i.json.source_type !== 'unsupported' && (i.json.content || '').length > 0);

if (!usable.length) {
  const reasons = items.map((i) => i.json.skipped || 'empty content').join(', ');
  throw new Error(`No usable documents. Reasons: ${reasons}`);
}

return usable.map((i) => ({ json: i.json }));

// Stage 1 extraction logic, written to be testable outside n8n.
// No dependencies.

// Stopwords are supplied at runtime (see the "Stopword lists" node), so the
// list can be the official YAKE one for the chosen language rather than
// anything hand-written here.
let ACTIVE_STOPWORDS = new Set();
let ACTIVE_CONNECTORS = new Set();

// Abbreviations that must not end a sentence.
const ABBREV = new Set(['fig', 'figs', 'no', 'nos', 'approx', 'etc', 'eg', 'ie', 'vs', 'cf', 'al',
  'dr', 'mr', 'mrs', 'ms', 'prof', 'st', 'vol', 'ch', 'sec', 'para', 'ref', 'max', 'min',
  'temp', 'dia', 'qty', 'incl', 'excl', 'ext', 'int', 'avg', 'std', 'mm', 'cm', 'kg', 'hr', 'rev']);

function decodeEntities(s) {
  return s
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&apos;/g, "'")
    .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(+d))
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCharCode(parseInt(h, 16)))
    .replace(/&amp;/g, '&');
}

// --- TMX ------------------------------------------------------------------
// Pulls the source-language segment out of each translation unit.
function parseTmx(xml, sourceLang) {
  const segments = [];
  // Comma-separated prefixes, e.g. 'nb,no,nn' for Norwegian.
  const wants = sourceLang.toLowerCase().split(',').map((w) => w.trim()).filter(Boolean);
  const tuRe = /<tu\b[^>]*>([\s\S]*?)<\/tu>/gi;
  const tuvRe = /<tuv\b([^>]*)>([\s\S]*?)<\/tuv>/gi;
  const segRe = /<seg\b[^>]*>([\s\S]*?)<\/seg>/i;
  const langRe = /(?:xml:)?lang\s*=\s*["']([^"']+)["']/i;

  let tu;
  while ((tu = tuRe.exec(xml)) !== null) {
    tuvRe.lastIndex = 0;
    let tuv;
    while ((tuv = tuvRe.exec(tu[1])) !== null) {
      const lang = (tuv[1].match(langRe) || [, ''])[1].toLowerCase();
      if (!wants.some((w) => lang.startsWith(w))) continue;
      const seg = tuv[2].match(segRe);
      if (!seg) continue;
      // Inline tags (<bpt>, <ph>, <it>) carry formatting, not text.
      const text = decodeEntities(seg[1].replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
      if (text) segments.push(text);
      break;
    }
  }
  return segments;
}

// --- sentence splitting ---------------------------------------------------
function splitSentences(text) {
  const cleaned = text.replace(/\s+/g, ' ').trim();
  if (!cleaned) return [];
  const out = [];
  let buf = '';
  const parts = cleaned.split(/([.!?]+)(\s+)/);
  for (let i = 0; i < parts.length; i += 3) {
    const chunk = parts[i] || '';
    const punct = parts[i + 1] || '';
    const space = parts[i + 2] || '';
    buf += chunk + punct;
    const lastWord = (chunk.match(/([A-Za-z]+)$/) || [, ''])[1].toLowerCase();
    const isAbbrev = ABBREV.has(lastWord);
    const isInitial = /\b[A-Z]$/.test(chunk);
    const isDecimal = /\d$/.test(chunk) && /^\s*\d/.test(parts[i + 3] || '');
    if (punct && !isAbbrev && !isInitial && !isDecimal) {
      out.push(buf.trim());
      buf = '';
    } else {
      buf += space;
    }
  }
  if (buf.trim()) out.push(buf.trim());
  return out.filter((s) => s.length > 0);
}

// --- tokenising -----------------------------------------------------------
function tokenise(sentence) {
  const raw = sentence.match(/[A-Za-z\u00C0-\u024F][A-Za-z\u00C0-\u024F'’\-]*|\d+(?:[.,]\d+)?/g) || [];
  return raw.map((t) => t.replace(/^['’\-]+|['’\-]+$/g, '')).filter(Boolean);
}

function isStop(token) {
  const t = token.toLowerCase();
  return ACTIVE_STOPWORDS.has(t) || ABBREV.has(t) || /^\d/.test(t) || t.length < 2;
}

// --- YAKE word-level features --------------------------------------------
function wordFeatures(sentences, tokensBySentence) {
  const stats = new Map();
  const totalSentences = sentences.length;

  tokensBySentence.forEach((tokens, sIdx) => {
    tokens.forEach((tok, pos) => {
      const key = tok.toLowerCase();
      let s = stats.get(key);
      if (!s) {
        s = { tf: 0, upper: 0, acronym: 0, sentences: new Set(), offsets: [], left: new Map(), right: new Map() };
        stats.set(key, s);
      }
      s.tf += 1;
      s.sentences.add(sIdx);
      s.offsets.push(sIdx);
      if (/^[A-Z][a-z]/.test(tok) && pos > 0) s.upper += 1;
      if (/^[A-Z]{2,}$/.test(tok)) s.acronym += 1;
      const prev = tokens[pos - 1];
      const next = tokens[pos + 1];
      if (prev && !isStop(prev)) s.left.set(prev.toLowerCase(), (s.left.get(prev.toLowerCase()) || 0) + 1);
      if (next && !isStop(next)) s.right.set(next.toLowerCase(), (s.right.get(next.toLowerCase()) || 0) + 1);
    });
  });

  const contentTf = [...stats.entries()].filter(([k]) => !isStop(k)).map(([, v]) => v.tf);
  const meanTf = contentTf.length ? contentTf.reduce((a, b) => a + b, 0) / contentTf.length : 1;
  const sd = contentTf.length
    ? Math.sqrt(contentTf.reduce((a, b) => a + (b - meanTf) ** 2, 0) / contentTf.length)
    : 0;
  const maxTf = contentTf.length ? Math.max(...contentTf) : 1;

  const scores = new Map();
  for (const [key, s] of stats) {
    // Casing: capitalised or acronym usage signals importance.
    const casing = Math.max(s.upper, s.acronym) / (1 + Math.log(1 + s.tf));

    // Position: terms appearing early are weighted higher.
    const sorted = [...s.offsets].sort((a, b) => a - b);
    const median = sorted[Math.floor(sorted.length / 2)];
    const position = Math.log(Math.log(3 + median));

    // Frequency, normalised against the spread of the whole corpus.
    const frequency = s.tf / (meanTf + sd || 1);

    // Relatedness: a word with many different neighbours behaves like a
    // stopword. Few, consistent neighbours suggest a real term.
    const leftTotal = [...s.left.values()].reduce((a, b) => a + b, 0);
    const rightTotal = [...s.right.values()].reduce((a, b) => a + b, 0);
    const dl = leftTotal ? s.left.size / leftTotal : 0;
    const dr = rightTotal ? s.right.size / rightTotal : 0;
    const relatedness = 1 + (dl + dr) * (s.tf / maxTf);

    // Dispersion: spread across many sentences beats clustering in one.
    const different = s.sentences.size / (totalSentences || 1);

    const score =
      (relatedness * position) /
      (casing + frequency / relatedness + different / relatedness || 1e-9);

    scores.set(key, { score, tf: s.tf, sentences: s.sentences.size });
  }
  return scores;
}

// --- candidate phrases ----------------------------------------------------
// Phrases are the runs of content words between stopwords and punctuation.
function candidatesFrom(tokens, ngramMax) {
  // Connectors are stopwords that may sit INSIDE a term but never at its edge.
  // Needed for Romance and other languages where multi-word terms are built
  // with prepositions: "valvola di sicurezza", "messa in servizio",
  // "chiffre d'affaires". Without this the boundary rule splits them apart.
  const runs = [];
  let current = [];
  for (const tok of tokens) {
    const t = tok.toLowerCase();
    if (ACTIVE_CONNECTORS.has(t)) {
      // Only continues a run that has already started.
      if (current.length) current.push(tok);
      continue;
    }
    if (isStop(tok)) {
      if (current.length) runs.push(current);
      current = [];
    } else {
      current.push(tok);
    }
  }
  if (current.length) runs.push(current);

  const isConnector = (tok) => ACTIVE_CONNECTORS.has(tok.toLowerCase());

  const out = [];
  for (const run of runs) {
    for (let n = 1; n <= Math.min(ngramMax, run.length); n += 1) {
      for (let i = 0; i + n <= run.length; i += 1) {
        const phrase = run.slice(i, i + n);
        // A term cannot begin or end with a connector.
        if (isConnector(phrase[0]) || isConnector(phrase[phrase.length - 1])) continue;
        // Two connectors in a row is a clause, not a term.
        let consecutive = 0;
        let bad = false;
        for (const tok of phrase) {
          consecutive = isConnector(tok) ? consecutive + 1 : 0;
          if (consecutive > 1) { bad = true; break; }
        }
        if (bad) continue;
        out.push(phrase);
      }
    }
  }
  return out;
}

// --- similarity for dedup -------------------------------------------------
function similarity(a, b) {
  if (a === b) return 1;
  const m = a.length;
  const n = b.length;
  if (!m || !n) return 0;
  if (Math.abs(m - n) / Math.max(m, n) > 0.5) return 0;
  let prev = Array.from({ length: n + 1 }, (_, i) => i);
  for (let i = 1; i <= m; i += 1) {
    const cur = [i];
    for (let j = 1; j <= n; j += 1) {
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    prev = cur;
  }
  return 1 - prev[n] / Math.max(m, n);
}

// --- main -----------------------------------------------------------------
function extract(documents, opts = {}) {
  const {
    ngramMax = 4,
    minChars = 15,
    dedupeThreshold = 0.85,
    minSegments = 1,
    topN = 500,
    includeExamples = 3,
    dedupeSegments = true,
    independenceRatio = 1.25,
    stopwords = [],
    extraStopwords = [],
    connectors = [],
  } = opts;

  ACTIVE_STOPWORDS = new Set([...stopwords, ...extraStopwords].map((w) => String(w).toLowerCase()));
  ACTIVE_CONNECTORS = new Set(connectors.map((w) => String(w).toLowerCase()));
  if (ACTIVE_STOPWORDS.size < 20) {
    throw new Error(
      `Only ${ACTIVE_STOPWORDS.size} stopwords supplied. Check the "Stopword lists" node has an entry for this language.`
    );
  }

  const log = { stopwords_used: ACTIVE_STOPWORDS.size, connectors_used: ACTIVE_CONNECTORS.size, files_seen: documents.length, files_parsed: 0, skipped: [], by_source_type: {} };
  const skip = (reason) => {
    const row = log.skipped.find((r) => r.reason === reason);
    if (row) row.count += 1;
    else log.skipped.push({ reason, count: 1 });
  };

  // ---- normalise into segments
  const segments = [];
  const seen = new Set();
  for (const doc of documents) {
    let raw = [];
    try {
      if (doc.source_type === 'tmx') {
        raw = parseTmx(doc.content, doc.source_lang || 'en');
        if (!raw.length) { skip('tmx_no_source_language_segments'); continue; }
      } else {
        raw = splitSentences(doc.content);
        if (!raw.length) { skip('no_extractable_text'); continue; }
      }
    } catch (e) {
      skip(`parse_error:${doc.source_type}`);
      continue;
    }
    log.files_parsed += 1;
    log.by_source_type[doc.source_type] = (log.by_source_type[doc.source_type] || 0) + 1;

    for (const text of raw) {
      if (text.length < minChars) { skip('below_min_chars'); continue; }
      const key = text.toLowerCase();
      if (dedupeSegments && seen.has(key)) { skip('duplicate_segment'); continue; }
      seen.add(key);
      segments.push({ text, source: doc.name, source_type: doc.source_type });
    }
  }

  log.segments_total = segments.length;
  if (!segments.length) return { terms: [], rows: [], log };

  // ---- sentence-level tokens, for the word scores
  const sentences = segments.map((s) => s.text);
  const tokensBySentence = sentences.map(tokenise);
  const wordScores = wordFeatures(sentences, tokensBySentence);

  // ---- candidate accumulation
  const cands = new Map();
  tokensBySentence.forEach((tokens, sIdx) => {
    const seg = segments[sIdx];
    for (const phrase of candidatesFrom(tokens, ngramMax)) {
      const surface = phrase.join(' ');
      const key = surface.toLowerCase();
      let c = cands.get(key);
      if (!c) {
        c = {
          term: surface,
          words: phrase.map((w) => w.toLowerCase()),
          n: phrase.length,
          occurrences: 0,
          segments: new Set(),
          sourceTypes: new Set(),
          sources: new Set(),
          examples: [],
          surfaces: new Map(),
        };
        cands.set(key, c);
      }
      c.occurrences += 1;
      c.segments.add(sIdx);
      c.sourceTypes.add(seg.source_type);
      c.sources.add(seg.source);
      c.surfaces.set(surface, (c.surfaces.get(surface) || 0) + 1);
      if (c.examples.length < includeExamples && !c.examples.includes(seg.text)) {
        c.examples.push(seg.text);
      }
    }
  });

  log.candidates_before_filter = cands.size;

  // ---- score each candidate (YAKE phrase formula; lower is better)
  const scored = [];
  for (const c of cands.values()) {
    if (c.segments.size < minSegments) continue;
    let product = 1;
    let sum = 0;
    let missing = false;
    for (const w of c.words) {
      const ws = wordScores.get(w);
      if (!ws) { missing = true; break; }
      product *= ws.score;
      sum += ws.score;
    }
    if (missing) continue;
    const yake = product / (c.occurrences * (1 + sum));
    // Most frequent surface form becomes the display term.
    const best = [...c.surfaces.entries()].sort((a, b) => b[1] - a[1])[0][0];
    scored.push({
      term: best,
      words: c.words,
      n: c.n,
      yake_score: yake,
      occurrences: c.occurrences,
      segments: c.segments.size,
      source_types: [...c.sourceTypes].sort(),
      sources: [...c.sources].sort(),
      examples: c.examples,
      merged_variants: [],
    });
  }

  log.dropped_below_min_segments = log.candidates_before_filter - scored.length;
  scored.sort((a, b) => a.yake_score - b.yake_score);

  // ---- collapse near-duplicates into the better-scoring candidate
  const kept = [];
  let merges = 0;
  for (const cand of scored) {
    const host = kept.find((k) => {
      if (k.n !== cand.n) return false;
      return similarity(k.term.toLowerCase(), cand.term.toLowerCase()) >= dedupeThreshold;
    });
    if (host) {
      host.occurrences += cand.occurrences;
      host.segments += cand.segments;
      host.source_types = [...new Set([...host.source_types, ...cand.source_types])].sort();
      host.merged_variants.push(cand.term);
      for (const ex of cand.examples) {
        if (host.examples.length < includeExamples && !host.examples.includes(ex)) host.examples.push(ex);
      }
      merges += 1;
    } else {
      kept.push(cand);
    }
  }

  log.merges = merges;
  log.candidates_after_dedupe = kept.length;

  // ---- suppress sub-phrases that add nothing
  // "relief valve" inside "pressure relief valve" is only worth keeping if it
  // also occurs independently. If nearly all its occurrences come from the
  // longer term, it is noise.
  const survivors = [];
  let suppressed = 0;
  for (const cand of kept) {
    const parent = survivors.find((s) => {
      if (s.n <= cand.n) return false;
      const hay = ` ${s.words.join(' ')} `;
      const needle = ` ${cand.words.join(' ')} `;
      if (!hay.includes(needle)) return false;
      // Independent use allowed for: occurrences beyond the parent's count.
      return cand.occurrences <= s.occurrences * independenceRatio;
    });
    if (parent) {
      parent.merged_variants.push(`(sub) ${cand.term}`);
      suppressed += 1;
    } else {
      survivors.push(cand);
    }
  }

  log.suppressed_subphrases = suppressed;
  log.candidates_final = survivors.length;
  kept.length = 0;
  kept.push(...survivors);

  const terms = kept.slice(0, topN).map((t, i) => ({
    rank: i + 1,
    term: t.term,
    word_count: t.n,
    yake_score: Number(t.yake_score.toPrecision(4)),
    occurrences: t.occurrences,
    segments: t.segments,
    source_types: t.source_types,
    sources: t.sources,
    merged_variants: t.merged_variants,
    examples: t.examples,
    lemma: null,
    pos_filtered: null,
    definition: null,
    translation: null,
  }));

  log.terms_returned = terms.length;

  const rows = terms.map((t) => ({
    rank: t.rank,
    term: t.term,
    word_count: t.word_count,
    yake_score: t.yake_score,
    occurrences: t.occurrences,
    segments: t.segments,
    source_types: t.source_types.join(' | '),
    merged_variants: t.merged_variants.join(' | '),
    examples: t.examples.join(' | '),
    definition: '',
    translation: '',
  }));

  return { terms, rows, log };
}

// ===========================================================================
// n8n glue. Run mode must be "Run Once for All Items".
// ===========================================================================

const settings = $('Settings').first().json;
const sw = $('Stopword lists').first().json;

const documents = $input.all().map((item) => ({
  name: item.json.file_name || 'unknown',
  source_type: item.json.source_type || 'text',
  source_lang: settings.tmx_lang || settings.source_lang,
  content: item.json.content || '',
}));

const result = extract(documents, {
  ngramMax: settings.ngram_max,
  minChars: settings.min_chars,
  dedupeThreshold: settings.dedupe_threshold,
  minSegments: settings.min_segments,
  topN: settings.top_n,
  includeExamples: settings.include_examples,
  dedupeSegments: settings.dedupe_segments,
  independenceRatio: settings.independence_ratio,
  stopwords: sw.stopwords,
  extraStopwords: sw.extra_stopwords,
  connectors: sw.connectors,
});

return [
  {
    json: {
      stage: 'stage_1_statistical',
      settings_used: settings,
      language: sw.language,
      stopwords: sw.counts,
      log: result.log,
      terms: result.terms,
      rows: result.rows,
    },
  },
];

// Flatten to one item per term for the spreadsheet node.
// Fails loudly on zero terms: otherwise the run would stop here silently and
// the job would sit in 'running' until it went stale.
const input = $input.first().json;
const rows = input.rows || [];
if (!rows.length) {
  const log = input.log || {};
  const skipped = (log.skipped || []).map((s) => `${s.reason} x${s.count}`).join(', ') || 'none';
  throw new Error(
    `No candidate terms found. Segments read: ${log.segments_total || 0}; skipped: ${skipped}. ` +
    'Check the source language matches the files, or lower "minimum segments".'
  );
}
return rows.map((row) => ({ json: row }));

// ===========================================================================
// STAGE 2 — lemmatisation and part-of-speech filtering.  *** STUB ***
//
// Passes stage 1's output straight through so the workflow runs end to end.
//
// The real version must:
//   1. Group inflected forms ("valve" / "valves") and SUM their occurrences
//      and segment counts, so the metrics stay correct.
//   2. Drop verb phrases ("inspected annually" is the classic example).
//   3. Set `lemma` and `pos_filtered` on each term.
//
// It must return the same shape: { stage, log, terms, rows }.
// ===========================================================================

// Reads stage 1 by name: its direct input is now the stage 1 spreadsheet.
const input = $('Stage 1 statistical extraction').first().json;

const terms = input.terms.map((t) => ({ ...t, lemma: null, pos_filtered: false }));

return [
  {
    json: {
      ...input,
      stage: 'stage_2_nlp_stub',
      log: {
        ...input.log,
        stage_2: {
          status: 'stub — no lemmatisation or POS filtering applied',
          terms_in: input.terms.length,
          terms_out: terms.length,
          merged_by_lemma: 0,
          dropped_by_pos: 0,
        },
      },
      terms,
    },
  },
];

// Whether the AI stage may run.
//
// The restricted list is deliberately NOT a setting: whether a client's
// content may reach a third-party model is a compliance decision, not a
// tuning knob.
const RESTRICTED_CLIENTS = [
  'example-restricted-client',
];

const input = $input.first().json;
const settings = $('Settings').first().json;
const client = (settings.client || '').trim().toLowerCase();

const restricted = RESTRICTED_CLIENTS.includes(client);
const requested = settings.run_ai_review === true;
const approved = settings.ai_review_approved === true;

return [
  {
    json: {
      ...input,
      gate: {
        client,
        requested,
        approved,
        restricted,
        may_run_ai: requested && approved && !restricted,
        reason: restricted
          ? 'Client is on the restricted list; AI stage blocked.'
          : !requested
            ? 'run_ai_review is false in Settings.'
            : !approved
              ? 'ai_review_approved is false in Settings.'
              : 'Approved.',
      },
    },
  },
];

const stage = $('Stage 2 NLP stub').first().json;
const terms = stage.terms || [];
if (!terms.length) throw new Error('Stage 2 returned no terms.');
return terms.map((t) => ({ json: t }));

// One request body per batch. Only terms, metrics and examples are sent —
// never whole files.
const batch = $input.all().map((i) => i.json);

const terms = batch.map((t) => ({
  term: t.term,
  occurrences: t.occurrences,
  segments: t.segments,
  examples: (t.examples || []).slice(0, 2),
}));

const instruction = [
  'You are reviewing candidate glossary terms extracted from a client corpus.',
  'For each term, decide whether it belongs in a terminology glossary and write a one-sentence definition grounded in the examples given.',
  'Reply with JSON only — no preamble, no code fences.',
  'Shape: {"results":[{"term":"...","keep":true,"reason":"...","definition":"..."}]}',
  'Set keep to false for verb phrases, generic language, and sentence fragments.',
].join(' ');

const body = {
  model: 'claude-sonnet-4-5',
  max_tokens: 2000,
  messages: [{ role: 'user', content: `${instruction}\n\nTerms:\n${JSON.stringify(terms, null, 2)}` }],
};

return [{ json: { llm_body: JSON.stringify(body), batch_size: batch.length, terms: batch } }];

// Merge the model's verdicts back onto the terms.
const response = $input.first().json;
const sent = $('Build AI request').first().json.terms || [];

let parsed = { results: [] };
try {
  const text = (response.content || [])
    .filter((b) => b.type === 'text')
    .map((b) => b.text)
    .join('\n')
    .replace(/```json|```/g, '')
    .trim();
  parsed = JSON.parse(text);
} catch (e) {
  return sent.map((t) => ({ json: { ...t, ai_error: `Could not parse model response: ${e.message}` } }));
}

const byTerm = new Map((parsed.results || []).map((r) => [String(r.term).toLowerCase(), r]));

return sent.map((t) => {
  const v = byTerm.get(String(t.term).toLowerCase());
  return {
    json: {
      ...t,
      ai_keep: v ? v.keep !== false : null,
      ai_reason: v ? v.reason || '' : 'no verdict returned',
      definition: v && v.definition ? v.definition : t.definition || '',
    },
  };
});

return $input.all().map((item) => {
  const t = item.json;
  const join = (v) => (Array.isArray(v) ? v.join(' | ') : v || '');
  return {
    json: {
      rank: t.rank,
      term: t.term,
      word_count: t.word_count,
      yake_score: t.yake_score,
      occurrences: t.occurrences,
      segments: t.segments,
      source_types: join(t.source_types),
      merged_variants: join(t.merged_variants),
      lemma: t.lemma || '',
      ai_keep: t.ai_keep === null || t.ai_keep === undefined ? '' : String(t.ai_keep),
      ai_reason: t.ai_reason || '',
      definition: t.definition || '',
      translation: t.translation || '',
      examples: join(t.examples),
      ai_error: t.ai_error || '',
    },
  };
});

// The run record, plus the three output files ready for upload: one item per
// file, each with its binary in 'data'. Keep the manifest with the glossary:
// it is what lets someone reproduce or question a result later.
const stage = $('Stage 2 NLP stub').first().json;
const gate = $('Check restricted list').first().json.gate || {};
const settings = $('Settings').first().json;
const finalRows = $('Final rows').all().map((i) => i.json);

const manifest = {
  run_at: new Date().toISOString(),
  job_id: settings.job_id,
  submitted_by: settings.submitted_by,
  client: settings.client || '',
  source_lang: settings.source_lang,
  tmx_lang: settings.tmx_lang,
  language_used: stage.language,
  stopwords: stage.stopwords,
  settings_used: settings,
  input_files: $('Documents in').all().map((i) => i.json.file_name),
  coverage: {
    files_seen: stage.log.files_seen,
    files_parsed: stage.log.files_parsed,
    by_source_type: stage.log.by_source_type,
    segments: stage.log.segments_total,
    skipped: stage.log.skipped,
    unsupported_in_folder: ($('Check job files').first().json.skipped_in_folder || 0),
  },
  extraction: {
    candidates_before_filter: stage.log.candidates_before_filter,
    merges: stage.log.merges,
    suppressed_subphrases: stage.log.suppressed_subphrases,
    dropped_below_min_segments: stage.log.dropped_below_min_segments,
    terms_returned: stage.log.terms_returned,
  },
  stage_2: stage.log.stage_2,
  ai_stage: {
    requested: gate.requested || false,
    approved: gate.approved || false,
    restricted: gate.restricted || false,
    ran: gate.may_run_ai || false,
    note: gate.reason || '',
    terms_with_parse_errors: finalRows.filter((r) => r.ai_error).length,
  },
};

const safe = (s) => String(s || '').replace(/[^\w.\-]+/g, '_').slice(0, 60);
const base = `${safe(settings.client)}_${settings.source_lang}_${settings.job_id}`;

const glossary = ($('Final spreadsheet').first().binary || {}).data;
const stage1 = ($('Stage 1 spreadsheet').first().binary || {}).data;
if (!glossary || !stage1) throw new Error('A spreadsheet node produced no file.');

const manifestFile = await this.helpers.prepareBinaryData(
  Buffer.from(JSON.stringify(manifest, null, 2), 'utf8'),
  `run_manifest_${base}.json`,
  'application/json',
);

return [
  { json: { kind: 'glossary', fileName: `glossary_${base}.xlsx`, manifest }, binary: { data: glossary } },
  { json: { kind: 'stage1', fileName: `stage1_candidates_${base}.xlsx` }, binary: { data: stage1 } },
  { json: { kind: 'manifest', fileName: `run_manifest_${base}.json` }, binary: { data: manifestFile } },
];

// AI stage did not run (the gate reason goes into the run manifest and the
// Jobs sheet). Same items as "Terms to items", without AI columns.
const stage = $('Stage 2 NLP stub').first().json;
const terms = stage.terms || [];
if (!terms.length) throw new Error('Stage 2 returned no terms.');
return terms.map((t) => ({ json: t }));

// ===========================================================================
// THE QUEUE. Jobs come from the Apps Script web page via the "Jobs" sheet.
//
// One job at a time: if a job is already running (and not stale), do nothing
// this tick. Otherwise take the oldest 'queued' job. Returning no items ends
// the run quietly, which is the normal outcome most minutes.
// ===========================================================================

const STALE_MINUTES = 45;   // keep in step with "Find stale jobs"

const rows = $input.all().map((i) => i.json).filter((r) => r.job_id);
const now = Date.now();
const isStale = (r) => {
  const t = Date.parse(r.started_at || '');
  return !t || now - t > STALE_MINUTES * 60000;
};

if (rows.some((r) => r.status === 'running' && !isStale(r))) return [];

const next = rows
  .filter((r) => r.status === 'queued')
  .sort((a, b) => String(a.submitted_at).localeCompare(String(b.submitted_at)))[0];

return next ? [{ json: next }] : [];

// Marks the job as running before any real work starts, so the next tick
// (and the web page) can see it has been picked up.
const job = $input.first().json;
return [{ json: { job_id: job.job_id, status: 'running', started_at: new Date().toISOString(), message: '' } }];

// A job left 'running' for too long means the run died without reporting
// (n8n restarted, the error workflow isn't set up, etc.). Mark it failed so
// the queue moves on and the submitter sees what happened.
const STALE_MINUTES = 45;   // keep in step with "Pick next job"

const now = Date.now();
return $input.all()
  .map((i) => i.json)
  .filter((r) => r.job_id && r.status === 'running')
  .filter((r) => {
    const t = Date.parse(r.started_at || '');
    return !t || now - t > STALE_MINUTES * 60000;
  })
  .map((r) => ({
    json: {
      job_id: r.job_id,
      status: 'failed',
      finished_at: new Date().toISOString(),
      message: `Stopped without reporting a result (running for more than ${STALE_MINUTES} min). Check the n8n executions list, then resubmit.`,
    },
  }));

// "List job files" always outputs at least one item, so an empty folder
// reaches here and fails with a clear message instead of stopping silently.
//
// The input may be a folder the user chose, holding PDFs, Word files or
// Google Docs. Only supported files are downloaded; the rest are listed in
// the run manifest as skipped.
const SUPPORTED = ['tmx', 'xml', 'txt', 'md'];

const all = $input.all().map((i) => i.json).filter((f) => f && f.id);
const isSupported = (f) => {
  const ext = String(f.name || '').split('.').pop().toLowerCase();
  return SUPPORTED.includes(ext) && !String(f.mimeType || '').startsWith('application/vnd.google-apps');
};
const keep = all.filter(isSupported);

if (!keep.length) {
  throw new Error(
    all.length
      ? `None of the ${all.length} files in the input folder can be used (needs .tmx, .xml, .txt or .md).`
      : "No files found in the job's input folder. Resubmit the job from the web page."
  );
}
return keep.map((f) => ({ json: { id: f.id, name: f.name, skipped_in_folder: all.length - keep.length } }));

// Write the result back to the job's row: links, counts and a short note.
const uploads = $input.all();
const sent = $('Run manifest').all();
const urls = {};
uploads.forEach((u, i) => {
  const kind = sent[i].json.kind;
  urls[kind] = u.json.webViewLink || `https://drive.google.com/file/d/${u.json.id}/view`;
});

const manifest = sent[0].json.manifest;
const notes = [];
if (manifest.ai_stage.ran) {
  notes.push('AI review ran.');
  if (manifest.ai_stage.terms_with_parse_errors) {
    notes.push(`${manifest.ai_stage.terms_with_parse_errors} terms have no AI verdict (response could not be parsed).`);
  }
} else if (manifest.ai_stage.requested) {
  notes.push(`AI review skipped: ${manifest.ai_stage.note}`);
}
const skipped = (manifest.coverage.skipped || []).filter((s) => !['below_min_chars', 'duplicate_segment'].includes(s.reason));
if (skipped.length) notes.push('Skipped: ' + skipped.map((s) => `${s.reason} x${s.count}`).join(', '));
if (manifest.coverage.unsupported_in_folder) notes.push(`${manifest.coverage.unsupported_in_folder} other files in the folder were ignored.`);
if (manifest.coverage.files_parsed < manifest.coverage.files_seen) {
  notes.push(`${manifest.coverage.files_seen - manifest.coverage.files_parsed} of ${manifest.coverage.files_seen} files produced no text.`);
}

return [{
  json: {
    job_id: manifest.job_id,
    status: 'done',
    finished_at: new Date().toISOString(),
    terms_returned: manifest.extraction.terms_returned,
    glossary_url: urls.glossary || '',
    stage1_url: urls.stage1 || '',
    manifest_url: urls.manifest || '',
    message: notes.join(' '),
  },
}];
